#!/usr/bin/env python3
from __future__ import annotations

import base64
import gzip
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / "docs" / "data" / "biblia-emanus"
LEDGER = DATA / "source-ledger.json"
MANIFEST = DATA / "manifest.json"
AUDIT = ROOT / "docs" / "biblia-emanus" / "IOSUA-AUDIT.md"

PAYLOAD = """"""

files = json.loads(gzip.decompress(base64.b64decode(PAYLOAD)).decode("utf-8"))
for filename, content in files.items():
    (DATA / filename).write_text(content, encoding="utf-8")

ledger = json.loads(LEDGER.read_text(encoding="utf-8"))
ledger["chapters"].update({
    "JOS.21": {"expectedVerses":45,"englishUrl":"https://ebible.org/engwebp/JOS21.htm","hebrewUrl":"https://ebible.org/hboWLC/JOS21.htm","textualVariantReview":["JOS.21.36","JOS.21.37","JOS.21.45"]},
    "JOS.22": {"expectedVerses":34,"englishUrl":"https://ebible.org/engwebp/JOS22.htm","hebrewUrl":"https://ebible.org/hboWLC/JOS22.htm","textualVariantReview":["JOS.22.10","JOS.22.11","JOS.22.22","JOS.22.34"]},
    "JOS.23": {"expectedVerses":16,"englishUrl":"https://ebible.org/engwebp/JOS23.htm","hebrewUrl":"https://ebible.org/hboWLC/JOS23.htm","textualVariantReview":["JOS.23.13","JOS.23.14"]},
    "JOS.24": {"expectedVerses":33,"englishUrl":"https://ebible.org/engwebp/JOS24.htm","hebrewUrl":"https://ebible.org/hboWLC/JOS24.htm","textualVariantReview":["JOS.24.3","JOS.24.12","JOS.24.19","JOS.24.26","JOS.24.32","JOS.24.33"]}
})
ledger["verifiedOn"] = "2026-08-04"
LEDGER.write_text(json.dumps(ledger, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")

manifest = json.loads(MANIFEST.read_text(encoding="utf-8"))
for chapter in range(21, 25):
    chapter_id = f"JOS.{chapter}"
    if chapter_id not in manifest["draftedChapters"]:
        manifest["draftedChapters"].append(chapter_id)
manifest["progress"].update(chaptersDrafted=74, versesDrafted=2191, chaptersApproved=74, chaptersPublished=74)
MANIFEST.write_text(json.dumps(manifest, ensure_ascii=False, separators=(",", ":")) + "\n", encoding="utf-8")

audit = AUDIT.read_text(encoding="utf-8").rstrip()
marker = "## Încheierea cărții — Iosua 21–24"
if marker not in audit:
    audit += """

## Încheierea cărții — Iosua 21–24

- lista celor patruzeci și opt de cetăți levitice este păstrată integral, inclusiv versetele 21:36–37 omise din unele tradiții;
- rezumatul împlinirii promisiunilor din 21:43–45 este citit împreună cu pasajele despre teritorii încă rămase;
- altarul din Iosua 22 este martor al unității legământului, nu un altar rival pentru jertfe;
- formula `El Elohim YHWH` din 22:22 este păstrată fără simplificare;
- conflictul dintre seminții este oprit prin investigație, mărturie și clarificarea intenției;
- avertismentele din Iosua 23 păstrează simultan iubirea de DOMNUL, ascultarea și consecințele idolatriei;
- alegerea din Iosua 24:15 este răspuns la istoria legământului, nu o prezentare a tuturor religiilor ca echivalente;
- `Nu veți putea sluji DOMNULUI` din 24:19 rămâne avertisment împotriva unui angajament superficial;
- `chesita` este păstrată ca unitate veche cu echivalență incertă;
- finalul extins al unor tradiții grecești după 24:33 este documentat, iar textul principal urmează încheierea masoretică.
""".rstrip()
AUDIT.write_text(audit + "\n", encoding="utf-8")
